using Microsoft.EntityFrameworkCore;using UAF.API.Authorization;using UAF.Application.Features.Documents;using UAF.Domain.Enums;using UAF.Infrastructure.Persistence;
namespace UAF.API.Endpoints;
public static class UniversityDocumentEndpoints{
 public static IEndpointRouteBuilder MapUniversityDocumentEndpoints(this IEndpointRouteBuilder app){
 app.MapGet("/api/v1/admissions/{applicationId:guid}/admission-letter.pdf",async(Guid applicationId,UafDbContext db,IUniversityDocumentPdfGenerator pdf,CancellationToken ct)=>{var data=await(from a in db.AdmissionApplications join p in db.AcademicPrograms on a.AcademicProgramId equals p.Id where a.Id==applicationId select new{a.ApplicationNumber,a.ApplicantFullName,Program=p.Name,a.Status}).SingleOrDefaultAsync(ct);if(data is null)return Results.NotFound();if(data.Status!=AdmissionStatus.Accepted)return Results.Conflict(new{error="Admission letter is available only after acceptance."});var university=await db.Universities.AsNoTracking().Select(x=>x.Name).FirstOrDefaultAsync(ct)??"University";var bytes=pdf.GenerateAdmissionLetter(university,data.ApplicationNumber,data.ApplicantFullName,data.Program,DateOnly.FromDateTime(DateTime.UtcNow));return Results.File(bytes,"application/pdf",$"admission-letter-{data.ApplicationNumber}.pdf");}).RequireAuthorization(AuthorizationPolicies.AdmissionsDecision).WithTags("Document Generation").WithName("DownloadAdmissionLetter");
 app.MapGet("/api/v1/fees/challans/{challanId:guid}/pdf",async(Guid challanId,UafDbContext db,IUniversityDocumentPdfGenerator pdf,CancellationToken ct)=>{var challan=await db.FeeChallans.AsNoTracking().SingleOrDefaultAsync(x=>x.Id==challanId,ct);if(challan is null)return Results.NotFound();var studentId=await db.StudentFeeAccounts.AsNoTracking().Where(x=>x.Id==challan.StudentFeeAccountId).Select(x=>x.StudentId).SingleOrDefaultAsync(ct);var student=await db.Students.AsNoTracking().Where(x=>x.Id==studentId).Select(x=>new{ x.FullName,x.RegistrationNumber }).SingleOrDefaultAsync(ct);if(student is null)return Results.NotFound();var lines=await db.FeeChallanLines.AsNoTracking().Where(x=>x.ChallanId==challanId).Select(x=>new FeeChallanPdfLine(x.FeeHeadCode,x.FeeHeadName,x.Amount)).ToListAsync(ct);var university=await db.Universities.AsNoTracking().Select(x=>x.Name).FirstOrDefaultAsync(ct)??"University";var bytes=pdf.GenerateFeeChallan(university,challan.ChallanNumber,student.FullName,student.RegistrationNumber,challan.IssueDate,challan.DueDate,challan.CurrencyCode,challan.Subtotal,challan.LateFeeAmount,lines);return Results.File(bytes,"application/pdf",$"fee-challan-{challan.ChallanNumber}.pdf");}).RequireAuthorization("Permission:finance.read").WithTags("Document Generation").WithName("DownloadFeeChallanPdf");
 return app;}
}
